// English source texts: scope help cards (Help → Show scope help, src/help/scopeHelp.ts).
// Scope texts checked against the sources in docs/research/scope-hilfe.md.
import type { Messages } from '../types';

export default {
  'help.menu': 'Show Scope Help',
  'help.open': 'What is {scope}?',
  'help.none': 'No help text for this view yet.',
  'help.read': 'How to read it',
  'help.try': 'Try it',
  'help.checkPrefix': 'Done when:',
  'help.done': 'Tried it',
  'help.progress': '{done} of {all} tasks tried',
  'help.pitfall': 'Watch out:',
  // --- scope texts (sources and checks: docs/research/scope-hilfe.md) ---
  'help.picture.one': "The source picture, optionally with an overlay: false colour, zebra, clipping, skin tone, green, luma, gamut, EBU R 103, neutral or focus peaking.",
  'help.picture.what': "First check of picture, focus and framing, and exposure right in the image. Zebra and false colour show where highlights clip or where skin sits without looking away from the subject. A click sets a probe point, a dragged box a measurement area for every scope; right-click clears.",
  'help.picture.read': "Zebra overlay: stripes on everything whose luma Y′ reaches the set level (default 95 %).\nFalse colour (palettes ARRI, Exposure, RED Video, Sony SDR, Sony S-Log3) colours level bands; the legend at bottom left lists the bands of the chosen palette.\nGamut warning: pixels with negative components in the target gamut (709/P3/2020), in three steps yellow/orange/magenta.\n\"EBU R 103\" overlay: amber = outside −5/105 %, red = outside the total range (codes 4–1019).\nGood: zebra only on speculars, not on faces or large areas.",
  'help.picture.try': "\"SMPTE 75 % bars + PLUGE\" test pattern, in ⚙ overlay \"Zebra\", level 95 % (default).",
  'help.picture.check': "stripes appear only on the 100 % white patch at the bottom, not on the 75 % grey at top left.",
  'help.picture.pitfall': "The picture passes through the computer's display colour space; monitor brightness says nothing about level. Scopes always measure the signal.",
  'help.wf-luma.one': "Brightness (Y′) of every pixel, left to right as in the picture.",
  'help.wf-luma.what': "The basic tool for exposure, black and white level. When shading, iris and master black (pedestal) are set here and cameras are compared on a grey scale. For legality it shows whether levels go above 100 % or below 0 %.",
  'help.wf-luma.read': "Horizontal: picture position left → right; vertical: level −7 … 110 % (scale also in 8/10 bit or cd/m²).\n0 % = black (code 64 at 10 bit), 100 % = nominal white (code 940).\nMagnifiers: black magnifier −5 … 15 %, highlight magnifier 85 … 110 %.\nOptional limit lines −5/105 % (EBU R 103); markers for HDR at 75 % HLG / 58 % PQ reference white and 38 % grey card, for log at 18 % grey.\nGood: black just above 0 %, white ≤ 100 %, grey scale as an even staircase.",
  'help.wf-luma.try': "\"SMPTE 75 % bars + PLUGE\" pattern, zoom \"full\"; then in ⚙ zoom \"black magnifier\".",
  'help.wf-luma.check': "in the full view the bars sit at 75.0 / 69.6 / 59.1 / 53.6 / 21.4 / 15.9 / 5.4 %; in the black magnifier the PLUGE area at bottom right shows +2 % and +4 % as two steps above 0 %.",
  'help.wf-luma.pitfall': "\"Skin at 70 IRE\" is a rule of thumb, not a standard; viewers watch the picture, not the waveform. There is no standardised SDR skin level.",
  'help.wf-color.one': "Luma waveform with every dot drawn in its picture colour.",
  'help.wf-color.what': "Shows at a glance which part of the picture sits at which level – useful when several objects share a level (face against a bright wall). Often replaces switching between picture and waveform during quick exposure.",
  'help.wf-color.read': "Axes and scale as the luma waveform.\nColour = pixel colour (brightness normalised so dark pixels stay visible), height = luma; colour does not change the measurement.\nGood: the key object (face, logo) is recognisable by colour and sits in the intended band.",
  'help.wf-color.try': "\"SMPTE 75 % bars + PLUGE\".",
  'help.wf-color.check': "the yellow bar appears yellow at 69.6 %, the blue one blue at 5.4 %.",
  'help.wf-color.pitfall': "Colour is not channel level: a red dot at 16 % means luma 16 %, not R′ = 16 %. Use the RGB parade for channels.",
  'help.wf-skin.one': "Luma waveform where only skin tones are coloured, the rest grey.",
  'help.wf-skin.what': "Finds faces in the waveform, even in busy pictures, and shows whether they sit at the same level across cameras. Helps racking presenters and talk shows, where skin is the most important element.",
  'help.wf-skin.read': "Band with two lines = luma range (default 30–80 %), drag the lines to change it; mouse wheel = hue tolerance around the 123° skin-tone line (default ±14°).\nOnly pixels inside both luma range and hue tolerance are coloured, all others grey.\nThe vectorscope shows the matching tolerance wedge around the skin-tone line.\nThe range can also be taken via ⚙ \"Range from measuring frame\" (first drag a measuring frame onto a face in the picture).\nGood: coloured dots grouped; with several cameras, at a similar height.",
  'help.wf-skin.try': "\"ColorChecker (approximation)\" pattern, defaults unchanged.",
  'help.wf-skin.check': "the two skin patches (top row, patches 1 and 2) appear in colour; blue, green, cyan and grey patches stay grey. The orange patch sits right at the tolerance limit and may be coloured too.",
  'help.wf-skin.pitfall': "Fixed skin levels exist only for HDR. SDR figures like \"70–80 IRE\" are NTSC-era practice, not a standard.",
  'help.wf-green.one': "Luma waveform that colours only greens (grass, foliage).",
  'help.wf-green.what': "Sport and OB: grass should look equally bright and equally green across all cameras. Shows the level and hue of the green without shirts or boards getting in the way.",
  'help.wf-green.read': "Band = luma range of the green qualifier (default 40–55 %), drag the lines to change it; hue 198° ± 20° (default), mouse wheel = tolerance. Can be shown in the vectorscope as the \"green wedge\".\nGood: grass dots as a tight band, at the same height on all cameras.",
  'help.wf-green.try': "\"ColorChecker (approximation)\"; drag the lower band line from 40 % to about 35 %.",
  'help.wf-green.check': "before, no patch is coloured (foliage sits at 39.4 % luma); afterwards only the foliage patch (top row, patch 4) appears in colour.",
  'help.wf-green.pitfall': "The 40–55 % default comes from BT.2408 for HLG HDR; SDR has no standard value. Under LED floodlights the hue can drift.",
  'help.wf-rgb.one': "R′, G′ and B′ overlaid in one waveform.",
  'help.wf-rgb.what': "Quick neutrality check: on grey and white all three channels must coincide. During white and black balance it shows at once which channel sticks out.",
  'help.wf-rgb.read': "Axes as the luma waveform; three traces in channel colours (mono/picture colours selectable), channels can be switched off individually.\nWhere all three coincide the trace turns white = neutral.\nGood: the grey scale as one white staircase without coloured fringes.",
  'help.wf-rgb.try': "\"Grey steps 11 (0–100 %)\".",
  'help.wf-rgb.check': "each step shows as one white line, no red, green or blue edge.",
  'help.wf-rgb.pitfall': "On colourful pictures the traces overlap and hide each other; use the parade to adjust single channels.",
  'help.parade.one': "R′, G′ and B′ side by side, one third of the width each.",
  'help.parade.what': "The main tool for white/black balance and shading: on a grey card or grey scale the three channels must stand equally high. White shading (saw/par) is adjusted per channel until each trace is flat. With *Touch Shading* (camera via lz-camera-bridge or the simulator) black and white per channel can be dragged right here.",
  'help.parade.read': "Three cells R | G | B, each with picture position left → right and level −7 … 110 %.\nSame height in all three = neutral (grey/white).\nFlat trace on an even white field = shading OK; bow = hotspot/edge fall-off, slope = saw error.\nGood: black of all channels level just above 0 %, white equally high.",
  'help.parade.try': "\"SMPTE 75 % bars + PLUGE\".",
  'help.parade.check': "in R, grey, yellow, magenta, red sit at 75 % and cyan, green, blue at 0 %; G and B accordingly (G: grey, yellow, cyan, green; B: grey, cyan, magenta, blue).",
  'help.parade.pitfall': "Black balancing with pedestal fully raised skews the result; raise it only enough that nothing clips. White balancing on paper with optical brighteners or under uneven light skews all channels. Grey cards are not always neutral.",
  'help.yrgb.one': "Luma and R′, G′, B′ side by side in four cells.",
  'help.yrgb.what': "Combines exposure (Y′) and channel balance in one view – handy when shading iris/pedestal and colour balance at the same time.",
  'help.yrgb.read': "Cells Y | R | G | B, scale as the luma waveform.\nY′ shows brightness, R/G/B the balance; on grey all four are equally high.\nGood: grey card at the same height in all four cells.",
  'help.yrgb.try': "\"Grey 50 %\" pattern.",
  'help.yrgb.check': "all four traces sit as a flat line at 50 %.",
  'help.yrgb.pitfall': "Y′ is weighted (green counts 71.5 %, blue 7.2 % in BT.709); a blue error barely shows in the Y cell, only in B.",
  'help.ycbcr.one': "Luma Y′ and the colour differences Cb and Cr side by side.",
  'help.ycbcr.what': "Shows the signal as it travels on SDI. Grey must sit exactly on the Cb and Cr zero line; any offset is a colour cast. The classic view for \"camera line-up / racking YCrCb\".",
  'help.ycbcr.read': "Y′ cell as the luma waveform; Cb and Cr are drawn offset by 50 % on the same scale, the 50 % line is their zero.\nAbove 50 %: Cb = towards blue, Cr = towards red; below: yellow and cyan/green respectively.\nGood: every neutral area exactly on the 50 % line of Cb and Cr.",
  'help.ycbcr.try': "\"Grey steps 11 (0–100 %)\".",
  'help.ycbcr.check': "Cb and Cr are one flat line at 50 % (= 0) across the whole width, Y′ a staircase from 0 to 100 %.",
  'help.ycbcr.pitfall': "HD and SD signals look different in Y′ and Cb/Cr for the same bars – not a fault.",
  'help.vector.one': "Hue as angle, saturation as distance from centre (Cb horizontal, Cr vertical).",
  'help.vector.what': "Checks colour bars, white balance and matrix settings and compares cameras for colour. White and grey belong in the centre; any offset is a cast. During white shading, high gain shows whether a white field stays a small dot in the centre.",
  'help.vector.read': "Boxes = 75 % targets, small circles = 100 % targets (only at ×1), matching the source matrix.\nDashed line = skin-tone line (123°), with the tolerance wedge of the skin waveform.\nZoom ×1/×2/×5; off-screen targets become triangles at the rim, \"×2 ZOOM\" or \"×5 ZOOM\" badge top right.\nOptional in ⚙: gamut limits 709/P3/2020, green wedge, own colour targets.\nGood: bar dots inside the boxes, grey as a dot in the centre.",
  'help.vector.try': "\"SMPTE 75 % bars + PLUGE\", zoom ×1.",
  'help.vector.check': "the six colour dots sit in the six 75 % boxes; grey, white and black form one dot in the centre. (Two extra dots outside the boxes come from −I and +Q in the bottom row.) Angles to check (ticks every 10°, 0° = +Cb to the right, counter-clockwise): yellow ≈ 175°, red ≈ 103°, magenta ≈ 50°, blue ≈ 355°, cyan ≈ 283°, green ≈ 230°.",
  'help.vector.pitfall': "Real charts (e.g. DSC ChromaDuMonde) are less saturated than bars and only reach the boxes at ×2. The skin-tone line (123°) is common practice, not a standard value.",
  'help.vector3.one': "Three vectorscopes side by side: shadows, mids and highlights of the same picture.",
  'help.vector3.what': "Separates a colour cast by brightness. A picture can be right in the skin tones and tip towards blue in the shadows – in a single vectorscope the two lie on top of each other.",
  'help.vector3.read': "Each circle only gets the pixels of its luma range; the boundaries are printed above the circles and can be changed in the ⚙ (30 and 70 % Y′ by default).\nThe lowest range reaches below black and the highest above white: sub-black and super-white belong to the picture.\nThe ⚙ also shows one circle alone and large.\nGood: all three clouds sit around the same centre.",
  'help.vector3.try': "Test pattern “SMPTE 75 % bars + PLUGE”.",
  'help.vector3.check': "Blue and red (the dark bars) only appear in the “shadows” circle, green and cyan in “mids”, and “highlights” keeps just the centre dot of white and grey. Yellow sits at Y′ 69.6 %, right on the boundary, and jumps from one to the other.",
  'help.vector3.pitfall': "The boundaries are luma boundaries, not exposure zones: a saturated colour can land in the mids although it is bright. Narrow ranges show little trace – that is not a fault, there is simply little picture in that range.",
  'help.hls.one': "Hue (HSL) as angle, HSL saturation as distance from the centre.",
  'help.hls.what': "Shows saturation independent of how bright a colour is. Helps judging dark or very bright colours that crowd towards the centre of the normal vectorscope, and reads like the vectorscope: red sits in the same place and the hues run the same way round.",
  'help.hls.read': "Angle = HSL hue; red where the vectorscope shows red for the source matrix, then yellow, green, cyan, blue, magenta in 60° steps counter-clockwise (spokes R, Yl, G, Cy, B, Mg).\nRadius = HSL saturation S = (max − min) / (1 − |max + min − 1|) of R′G′B′ (limited to 0–100 %); rings at 25/50/75/100 %.\nCentre = neutral (grey, white, black).\nNo target boxes and no skin-tone line.\nGood: neutrals in the centre; the same colour at different brightness at the same radius.",
  'help.hls.try': "\"SMPTE 75 % bars + PLUGE\".",
  'help.hls.check': "the six colour bars sit on the 100 % ring, each on its spoke (R, Yl, G, Cy, B, Mg); grey, white and black sit in the centre. Although the bars are only at 75 % level they reach the outer ring, because HSL saturation does not depend on brightness. (Two further dots on the ring come from −I and +Q in the bottom row.)",
  'help.hls.pitfall': "Near black and white a tiny channel difference produces high HSL saturation; shadow noise then looks \"saturated\". Values below 0 % and above 100 % are clipped first. Use the normal vectorscope for legality and bar levels.",
  'help.cie.one': "Chromaticity of every pixel in CIE 1931 xy or 1976 u′v′, with gamut triangles.",
  'help.cie.what': "Shows which colour space the material actually uses and whether colours exceed Rec.709 (HDR/WCG, camera gamuts). Helps checking conversions (CST, LUT) and graphics.",
  'help.cie.read': "Horseshoe = spectral locus (labelled in nm); triangles Rec.709, P3-D65, Rec.2020, plus the source gamut when it is none of these; the target solid and thicker. Circle at D65, crosses at D55 and DCI.\nBottom left: the share of the picture outside the target (⚙ → target gamut), followed by the part clearly outside – the same rule as the gamut warning in the picture view, which paints those pixels.\nLightness is missing: light and dark versions of one colour land on the same point.\nGood: points inside the target gamut; grey on D65.",
  'help.cie.try': "\"SMPTE 75 % bars + PLUGE\".",
  'help.cie.check': "red, green, blue sit exactly on the Rec.709 corners (R x 0.640/y 0.330, G 0.300/0.600, B 0.150/0.060), yellow, cyan, magenta on its edges, grey on D65 (0.3127/0.3290).",
  'help.cie.pitfall': "75 % and 100 % bars land on the same spot – the diagram shows no level. u′v′ (switchable in ⚙) is more uniform for colour differences than xy. −I and +Q from the bottom row show as extra points.",
  'help.diamond.one': "Two Tektronix-style diamonds showing R′G′B′ balance and per-channel gamut errors.",
  'help.diamond.what': "Ideal for grey balance when shading: a correctly balanced camera on a grey scale or white field gives a vertical line. At the same time the diamond shows how much headroom remains to the gamut limit.",
  'help.diamond.read': "Top: B′+G′ (vertical) vs B′−G′ (horizontal); bottom: −(R′+G′) vs R′−G′.\nCentre = black, top/bottom apex = white; grey = vertical line; dashed inner diamond = 50 %.\nBend in the top diamond → blue/green error, bottom → red/green error; green errors show in both.\nEverything legal stays inside both diamonds.\nGood: straight vertical line; nothing outside.",
  'help.diamond.try': "\"Grey ramp 0–100 %\".",
  'help.diamond.check': "a vertical line from centre to apex in both diamonds.",
  'help.diamond.pitfall': "Hardware scopes low-pass filter short overshoots, lz-scopes does not: sharp edges can poke just outside without the signal being illegal under R 103 (which uses a measurement filter).",
  'help.cube.one': "Point cloud of all pixels as a 3D volume (R′G′B′ cube, Y′CbCr, HSV, CIE XYZ, CIELAB, LCh or ICtCp), freely rotatable.",
  'help.cube.what': "Shows the whole colour volume at once: which corners (primaries, secondaries, white, black) are reached or clipped and whether a cast shifts the grey axis. Useful for LUT and conversion checks that vectorscope and diamond only show as projections.",
  'help.cube.read': "Wireframe = target gamut (in the R′G′B′ cube the 0–100 % cube, plus a 25 % grid); dashed grey axis from black to white.\nDrag = rotate, ⇧+drag = pan, wheel or pinch = zoom, double-click = reset.\nThe probe point from the picture shows as a circle in the volume. Optionally the cube shows the volume of a loaded LUT.\nGood: grey on the axis, colours inside the wireframe.",
  'help.cube.try': "\"SMPTE 75 % bars + PLUGE\", space R′G′B′ cube, probe point in the picture on the yellow bar.",
  'help.cube.check': "the bars sit on the corners of a smaller cube with 75 % edge length (at the 75 ticks of the axes); the probe circle sits on the corner R′ 75 / G′ 75 / B′ 0.",
  'help.cube.pitfall': "Distance in R′G′B′ is not perceptually uniform; for \"how visible is the difference\" use CIELAB/ICtCp and ΔE (settings → \"ΔE at probe\", shown in the picture and measurements panels).",
  'help.satlum.one': "Each pixel as a dot: horizontal luma Y′, vertical saturation |CbCr|.",
  'help.satlum.what': "Shows where in the tonal range colour sits: saturated highlights (gamut risk) or coloured shadows (cast in the blacks, e.g. wrong black balance). Helps with black balance and knee/low-key saturation.",
  'help.satlum.read': "x = Y′ in % (same range as the waveform), y = saturation |CbCr|/0.5 in %, scale up to 120 % (100 % ≈ fully saturated primary).\nNeutral pixels lie at the bottom; bulge top right = saturated highlights, top left = coloured shadows.\nGood: no raised dots at bottom left (black) or bottom right (white).",
  'help.satlum.try': "\"SMPTE 75 % bars + PLUGE\".",
  'help.satlum.check': "bars between about 75 % (yellow, blue) and 89 % saturation (green, magenta), each at its luma (e.g. yellow at 69.6 %); grey, white, black at 0 % (values computed from BT.709).",
  'help.satlum.pitfall': "The scale is |CbCr|/0.5, not HSL saturation; dark colours show small values here even if they look rich.",
  'help.chplot.one': "Two channels plotted against each other (R′/G′, R′/B′, G′/B′, Y′/Cb, Y′/Cr, Cb/Cr).",
  'help.chplot.what': "Shows channel balance across the whole range: on grey, R′/G′ dots fall on the diagonal. A gamma or black error in one channel shows as a curve or offset – the grey-scale \"tracking\" check.",
  'help.chplot.read': "Dashed diagonal = equal channels (only for the R′G′B′ pairs).\nOffset parallel to the diagonal = black/pedestal error; different slope = gain error; bow = gamma error.\nCb/Cr axes are labelled −0.50 … +0.50, centre = 0.\nGood: the grey scale as a straight line on the diagonal.",
  'help.chplot.try': "\"Grey ramp 0–100 %\", pair R′/G′.",
  'help.chplot.check': "one continuous line exactly on the diagonal.",
  'help.chplot.pitfall': "Colourful content naturally lies off the diagonal; the reading is only valid on neutral targets.",
  'help.minmax.one': "Darkest and brightest Y′ of each picture line, top to bottom as in the picture.",
  'help.minmax.what': "Quickly finds lines with excursions (super-white, sub-black) and shows contrast across the picture height, e.g. for black shading or sky/ground gradients.",
  'help.minmax.read': "Vertical: picture line (top = line 1); horizontal: Y′ −7 … 110 %. Blue trace = minimum, green = maximum.\nLimits EBU R 103 (−5/105 %, default) or legal (0/100 %) as red dashed lines; excursions turn the trace red.\nUp to four custom target lines (⚙, in %).\nGood: no red; the min–max gap shows the line's contrast.",
  'help.minmax.try': "\"SMPTE 75 % bars + PLUGE\", ⚙ limits legal.",
  'help.minmax.check': "in the top area min ≈ 5.4 % (blue) and max ≈ 75 %, at the bottom min = 0 % and max = 100 % (white patch); nothing red.",
  'help.minmax.pitfall': "With R′G′B′ and browser sources values below 0/above 100 % are already clipped; excursions only show in the bridge mode *16 bit Y′CbCr* and with test patterns carrying exact 10-bit codes.",
  'help.qclog.one': "Time-stamped list of level, picture and audio faults on all live sources.",
  'help.qclog.what': "Runs during a show or recording and records when and for how long something went wrong: R 103 violation (−5/105 % and total range 4–1019), white clipping, super-white, sub-black, black frame, freeze, silence. Export as CSV.",
  'help.qclog.read': "Each row = one event from start to end, with clock time, source time code and worst value.\nChecked four times a second; thresholds in ⚙ (defaults: clipping from 0.5 % of pixels, black frame Y′ max < 2 %, silence < −60 dBFS for 2 s, freeze 2 s); event types can be shown or hidden individually.\nR 103 reports only from 1 % of the area outside −5/105 %.\nGood: an empty list.",
  'help.qclog.try': "\"Grey 50 %\" pattern, switch to the \"Black\" pattern for a few seconds and back.",
  'help.qclog.check': "a \"black frame\" event with start, end and duration appears.",
  'help.qclog.pitfall': "Freezes count only for live sources and playing files, not for test patterns or paused files. R 103 is only checked in the Y′CbCr path. Patterns with 100 % white (e.g. SMPTE bars) already trigger \"white clipping\".",
  'help.timeline.one': "Colour, hue, saturation and luma of the last 10 s, 1 min or 5 min as strips.",
  'help.timeline.what': "Shows change over time: iris jumps, drifting auto white balance (ATW), flicker, lighting changes at events. A \"movie barcode\" reveals cuts and moods.",
  'help.timeline.read': "Horizontal: time (right = now). Top the mean colour (movie barcode), below it hue shares (bright = a lot of this hue), saturation (mean and 95 %) and luma (min–max range, line = mean).\nSampled ten times a second on a 96×54 grid (finer selectable) or once per frame.\nGood: calm, even strips where the picture should be steady.",
  'help.timeline.try': "Toggle between \"SMPTE 75 % bars + PLUGE\" and \"Grey 50 %\".",
  'help.timeline.check': "the luma and saturation strips show the changes as sharp edges; on grey the saturation drops to 0.",
  'help.timeline.pitfall': "The timeline always evaluates the whole frame, a measurement box has no effect here; a small badly exposed area barely shows – use the waveform or measurements with a box for that.",
  'help.hist.one': "How many pixels sit at which level – RGB, luma or split.",
  'help.hist.what': "Quick overview of exposure and clipping without picture position. Shows whether highlights or shadows are clipped (pile-up at the edge) and what percentage clips.",
  'help.hist.read': "Horizontal: level 0–100 %; vertical: pixel count (linear or log).\nTop left the clipping share at the bottom (▼) and top (▲), each the highest of the channels; per channel in the *Measurements* panel.\nDisplay RGB, luma or split; switchable in ⚙.\nGood: no tall pile exactly at 0 % or 100 % unless intended.",
  'help.hist.try': "\"Grey ramp 0–100 %\", display luma.",
  'help.hist.check': "the distribution is roughly equally high across the whole range (flat).",
  'help.hist.pitfall': "The histogram does not say *where* clipping happens; 0.1 % clipping can be a face. Cross-check with zebra or waveform.",
  'help.stats.one': "Numbers for the source: format, Y′ min/max/mean, clipping, R 103, MaxCLL/MaxFALL.",
  'help.stats.what': "Provides hard numbers for logs and acceptance: whether levels are in range, how much area violates R 103, and for PQ HDR the content light levels. Also shows transport and dropped frames.",
  'help.stats.read': "Y′ min/max/mean in % (for HDR and log also in cd/m² or scene %); clipping per channel; MaxCLL/MaxFALL for PQ only.\nR 103: share outside −5/105 % (reported from 1 %) and outside 4–1019 (hard limit).\nNotes when the source is R′G′B′ (clipped) or full range.\nGood: Y′ min ≥ −5 %, Y′ max ≤ 105 %, no R 103 warning.",
  'help.stats.try': "\"SMPTE 75 % bars + PLUGE\".",
  'help.stats.check': "Y′ max = 100 %, Y′ min = 0 %, note that the source is R′G′B′ (clipped). With \"SMPTE 75 % bars + PLUGE (LZ)\" (exact 10-bit codes) Y′ min shows −2 % because of the PLUGE stripe.",
  'help.stats.pitfall': "R 103 is defined for narrow range; with full-range sources and R′G′B′ streams the result is only a percentage comparison (the app says so).",
  'help.match.one': "Compares a probe point or box mean with a target or a second camera.",
  'help.match.what': "Camera matching and brand colours: shows how far a colour is from the target (client hex, logo) or from the same object in another camera, and translates the correction into camera terms (multi-matrix, white balance) and Resolve values.",
  'help.match.read': "Swatches side by side; ΔE00 (SDR) or ΔITP (HDR), plus ΔL/ΔC/ΔH, hue, saturation.\nTraffic light: green up to ΔE 1 (just noticeable), yellow up to the set tolerance, red above; ΔE00 ≈ 1 is a rule of thumb, not a fixed threshold.\nCorrection suggested in words and values.\nGood: ΔE00 near 0, ΔH near 0 (hue matches).",
  'help.match.try': "\"SMPTE 75 % bars + PLUGE\" pattern, probe point on the yellow bar in the picture panel; in the colour match ⚙ \"+ Measuring point\", then pick this target under \"Compare with\".",
  'help.match.check': "ΔE00 ≈ 0, verdict \"barely distinguishable\"; with the probe on the cyan bar a large value and \"clearly different\".",
  'help.match.pitfall': "Camera matching is only reliable under the same light on the same chart; copying settings from camera to camera is not enough. Multi-matrix also moves neighbouring hue ranges.",
  'help.tiles.one': "The same scope for up to eight sources side by side, each tile labelled with the camera ID.",
  'help.tiles.what': "Camera matching at a glance: all cameras on the same waveform, parade or vectorscope, so black, white and colour can be compared without switching the source. ⚙ picks the scope and the sources; nothing ticked shows the first eight video sources.",
  'help.tiles.read': "Strip above each tile: number in the source list and name of the source.\nAll tiles use the same settings (brightness, colours, zoom, reference trace).\nGood: matched cameras have the same trace height and shape in every tile.",
  'help.tiles.try': "Add a second test pattern source (\"+ Source\" → \"Test pattern\", \"Grey steps 11 (0–100 %)\"), keep the first on \"SMPTE 75 % bars + PLUGE\", then pick \"Waveform Luma\" as the tile scope.",
  'help.tiles.check': "two tiles labelled 1 and 2: tile 1 shows the bar levels, tile 2 the eleven grey steps from 0 to 100 %.",
  'help.tiles.pitfall': "Each tile is small: fine level differences are easier to read with the reference trace (⚙ → Reference) than by comparing tiles by eye.",
  'help.noise.one': "Random noise of Y′, R′, G′ and B′ in the measuring frame: level, σ in %, mVrms and dB, plus S/N.",
  'help.noise.what': "Compares cameras and gain settings: black noise with the lens capped, picture noise on an even grey. A camera with more gain or a noisier sensor stands out at once, also between brands.",
  'help.noise.read': "σ = RMS deviation from the mean (with \"remove shading\" from a fitted surface, so lens shading does not count).\ndB = 20·log10(σ / 100 %); −50 dB = 0.32 %. S/N = minus that value.\nThe quantisation floor shows how low this signal path can measure at all (8 bit ≈ −59 dB, 10 bit narrow ≈ −70 dB).\nGood: matched cameras within about 1 dB of each other at the same gain.",
  'help.noise.try': "\"Grey 50 %\" test pattern, no measuring frame.",
  'help.noise.check': "level 50.2 % in all channels and σ 0.00 / −∞ dB: test patterns carry no noise. With a camera, the same reading on a capped lens shows its black noise.",
  'help.noise.pitfall': "A scaled analysis picture averages noise away; measure bridge streams at width \"native\". Edges or texture in the frame count as noise – keep the frame on a flat area.",
  'help.wshading.one': "Flatness of Y′ and each colour channel over a white field, as a map and split into saw and par, horizontal and vertical.",
  'help.wshading.what': "White shading: lenses and prisms make the centre brighter than the edges or tint one side. The values say which camera control to turn – per channel saw H/V first, then par H/V – until the field is flat.",
  'help.wshading.read': "Map: each cell's deviation from the field mean (warm = brighter, blue = darker), or the colour cast R′−G′ / B′−G′.\nSaw H = right edge − left edge, Saw V = bottom − top, Par = edges − centre, in % of the mean; spread = max − min of the fitted surface.\nGood: all values within a few tenths of a percent, colour map neutral.",
  'help.wshading.try': "\"Grey ramp 0–100 %\" test pattern, map Y′.",
  'help.wshading.check': "Saw H large and positive (the ramp rises to the right), Saw V and both pars near 0; with \"Grey 50 %\" every value is 0.",
  'help.wshading.pitfall': "The field must really be even: a lamp hotspot or an off-axis diffuser shows up as lens shading. Keep the frame free of texture and slightly defocus.",
  'help.skinall.one': "The skin tones of several cameras as coloured dot clouds in one vectorscope, each with its centre, hue and saturation.",
  'help.skinall.what': "Matching faces across cameras: the same presenter seen from different angles should have the same skin hue and saturation everywhere. Pixel-by-pixel comparison fails with different framings; comparing the skin distributions works. Faces come from face tracking (⚙ \"Find faces\").",
  'help.skinall.read': "One colour per source; dots = skin pixels, cross = their centre.\nH = hue angle (skin-tone line 123°) with the offset from the line; S = saturation; ΔH/ΔS against the reference camera.\nGood: all crosses on top of each other, ΔH within about ±2°.",
  'help.skinall.try': "\"ColorChecker (approximation)\" test pattern, drag a measuring frame over the two skin patches at top left.",
  'help.skinall.check': "two tight clusters on the skin-tone line (the patches lie at 122.2° and 123.3°, saturation 16 % and 22 %), the cross at about 123°; without the frame the orange patch at 136.9° pulls the cross away from the line.",
  'help.skinall.pitfall': "Light on the face differs between camera angles (key vs. fill side); compare cameras on the same side of the face, and switch face tracking on in every source.",
  'help.chart.one': "A colour chart seen by every camera, compared patch by patch against the reference camera, with a matrix that would bring each camera onto it.",
  'help.chart.what': "Matching cameras on an object they all see: a ColorChecker Classic in front of each camera. The chart is found through four corners (clicked, the measuring frame or the whole picture), so different angles and sizes do not matter.",
  'help.chart.read': "One block per camera, 6 × 4 cells in the layout of the chart; each cell is the ΔE00 (ΔITP for PQ/HLG) of that patch against the same patch of the reference.\nMean and maximum above the cells; the 3×3 matrix below (rows R, G, B, linear light) with ΔE before → after.\nGood: every cell green (ΔE ≤ 1), mean below the tolerance.",
  'help.chart.try': "Two test-pattern sources, both \"ColorChecker (approximation)\"; panel without corners (the chart fills the picture).",
  'help.chart.check': "Both blocks all green with ΔE 0,0; switch one source to a different pattern and its cells turn red.",
  'help.chart.pitfall': "Light on the chart must be the same for all cameras (no shadow, no glare from one angle); a patch with a reflection drives the matrix. The matrix is computed, not applied: enter it in the camera or a CST.",
  'help.drift.one': "Black floor and neutral balance of every camera against the mean of all cameras, with an alarm when one drifts away.",
  'help.drift.what': "Watching a matched camera group during the show: LED light, clouds or a warming camera move one camera away from the others. The guard compares each camera with the group, not with a fixed target.",
  'help.drift.read': "One row per camera: black (Y′ black centroid in %), Δ black, ΔR−G and ΔB−G of the median against the group mean, all in percentage points.\nGreen = inside the tolerance, red = drifted.\nGood: all rows green, deltas near 0.",
  'help.drift.try': "Two test-pattern sources with the same pattern, then one switched to another pattern; or the shading simulator next to a test pattern and Touch Shading on the simulator.",
  'help.drift.check': "Same pattern: every Δ 0,0 and green. Raise Master Black of the simulator: its row turns red with a positive Δ black.",
  'help.drift.pitfall': "The cameras must see comparable content: a dark wide shot against a bright close-up is no drift. Measuring frames on the same grey object make the comparison fair.",
  'help.audio-meter.one': "Sample peak, true peak and loudness (M, S, I, LRA) to EBU R 128.",
  'help.audio-meter.what': "Keep level and loudness for broadcast and streaming: programme at −23 LUFS, peaks not above −1 dBTP. Also shows overs and the −18 dBFS alignment level.",
  'help.audio-meter.read': "Bar per channel: sample peak (100 ms), white mark = true peak, 3 s hold; marks at −18 dBFS (R 68) and −1 dBTP (R 128).\nM (400 ms), S (3 s), I (integrated, gated) on EBU +9 or +18 scale, absolute LUFS or relative LU (0 LU = −23 LUFS).\nLRA flagged \"unstable\" during the first 60 s.\nGood: I = −23.0 LUFS (±0.5 LU; ±1 LU for live programmes where tighter is not achievable), max TP ≤ −1 dBTP.",
  'help.audio-meter.try': "Tone generator: 1 kHz sine, stereo, −18 dBFS, \"→ as measurement source\".",
  'help.audio-meter.check': "peak −18 dBFS on both channels; M and S show the value the generator states as target (about −18 LUFS = +5 LU for this stereo sine).",
  'help.audio-meter.pitfall': "dBFS (peak) and LUFS (loudness) are different quantities; a programme peaking at −1 dBTP can still be far too loud or too quiet.",
  'help.audio-loudness.one': "Momentary and short-term loudness of the last 1 to 60 minutes with a target band.",
  'help.audio-loudness.what': "Shows whether a programme stays on target over time and where loud inserts, applause or quiet presenters were. True-peak overs are marked.",
  'help.audio-loudness.read': "Horizontal: time; vertical: loudness; target band ±1 LU around the target.\nMarks where true peak > −1 dBTP.\nGood: S curve mostly inside the band, no peak marks.",
  'help.audio-loudness.try': "Generator sine −23 dBFS stereo, after a minute switch to −18 dBFS.",
  'help.audio-loudness.check': "the curve jumps up 5 LU and leaves the target band.",
  'help.audio-loudness.pitfall': "Short-term values swing a lot with speech; R 128 compliance is judged on integrated loudness I over the whole programme.",
  'help.audio-spectrum.one': "Frequency content of the audio via FFT on a log frequency axis.",
  'help.audio-spectrum.what': "Finds hum (50/100 Hz), whistles, feedback and missing top end; checks test tones and lines.",
  'help.audio-spectrum.read': "Horizontal: frequency (log), vertical: level in dB.\nTilt 0/3/4.5 dB/oct compensates the natural roll-off; third-octave bands optional.\nGood: no narrow standing peaks that do not belong to the programme.",
  'help.audio-spectrum.try': "Generator 1 kHz sine.",
  'help.audio-spectrum.check': "a single peak at 1 kHz. Then pink noise with 3 dB/oct tilt as a line:",
  'help.audio-spectrum.pitfall': "FFT size sets resolution: a small FFT separates low frequencies poorly, a large one reacts slowly.",
  'help.audio-phase.one': "Stereo image as an M/S display with a correlation meter.",
  'help.audio-phase.what': "Checks stereo width, mono compatibility and polarity. A reversed channel can cancel speech on mono playback (phone, radio).",
  'help.audio-phase.read': "Vertical line = mono (L = R); L top left, R top right.\nHorizontal line = out of phase (L = −R).\nCorrelation: +1 = mono, 0 = uncorrelated, −1 = out of phase.\nGood: cloud mostly vertical, correlation mostly positive.",
  'help.audio-phase.try': "Generator sine, quick select L+R.",
  'help.audio-phase.check': "vertical line, correlation +1. Then L−R:",
  'help.audio-phase.pitfall': "Brief negative correlation occurs with wide reverb; only sustained negative values indicate reversed polarity. The correlation meter has no freely available standard definition (600 ms window is an own choice).",
  'help.audio-check.one': "Recognises line idents, reports channel faults and measures audio-to-video offset.",
  'help.audio-check.what': "Line check before air: do all channels arrive in the right order and polarity at −18 dBFS? Plus lip sync between flash and beep.",
  'help.audio-check.read': "Recognised: EBU stereo ident (R 49), GLITS, BLITS, EBU multichannel ident (Tech 3304), own channel ident.\nReports: \"L/R swapped\", \"polarity inverted\", \"channel missing\", wrong channel order, level vs −18 dBFS.\nA/V offset positive = sound ahead of vision; judged per BT.1359-1: detectable from about +45/−125 ms, acceptable up to about +90/−185 ms.\nGood: no yellow or red report, offset within +25/−100 ms.",
  'help.audio-check.try': "Tone generator \"EBU stereo ident\", level −18 dBFS, \"→ as measurement source\".",
  'help.audio-check.check': "\"EBU stereo ident (R 49)\" recognised, only green reports (L/R assigned correctly, in phase, level −18 dBFS). Then quick select R instead of L+R:",
  'help.audio-check.pitfall': "The A/V offset applies only to the measured path; without a one-time calibration the computer's own picture output is not guaranteed in sync.",
  'help.genlock.one': "Status of house sync at a DeckLink reference input, plus frame timing and time code.",
  'help.genlock.what': "In multi-camera systems all cameras and playout must lock to the same reference, otherwise the picture jumps on a cut. The panel shows whether the reference is present and locked.",
  'help.genlock.read': "Lock status, detected format (black burst for SD, tri-level for HD), set genlock offset, input status.\nFrame timing of DeckLink/NDI sources on the SMPTE ST 2059-1 grid (position, spread, drift in ppm).\nGood: \"locked\", matching format, drift near 0 ppm.",
  'help.genlock.try': "Feed tri-level sync into the DeckLink reference input.",
  'help.genlock.check': "reference \"locked\", format \"tri-level sync (HD format)\". Without cable: \"not locked\".",
  'help.genlock.pitfall': "The DeckLink SDK does not report the input-to-reference timing offset; the panel therefore shows no timing measurement like a hardware scope. Not yet tested with hardware.",
  'help.clock.one': "Time-of-day time code, source time code, LTC and PTP status.",
  'help.clock.what': "Time reference for broadcast and recording: compare camera time code with time of day, read LTC from audio, check a PTP grandmaster (ST 2110/2059).",
  'help.clock.read': "Time of day per ST 2059-1 (system time → TAI → time code); \"System clock – not a reference\" while no PTP corrects it.\nSource time code (container start tag or SEI via the bridge, video files in the browser count from 0) and difference to time of day in frames.\nPTP: grandmaster, domain, clockClass, offset (software estimate).\nGood: difference 0 frames, PTP received.",
  'help.clock.try': "Open the \"Clock / time code\" panel with no PTP on the network.",
  'help.clock.check': "the time-of-day time code runs and is marked \"System clock – not a reference\"; with the bridge running, the PTP line reports \"no PTP received\".",
  'help.clock.pitfall': "Above 30 fps the time code counts 0…49/59 like editors; LTC per ST 12-1 only knows frame pairs. Software time stamps are only an estimate for PTP.",
  'help.light-cie.one': "Measured chromaticity of the light in CIE 1976 u′v′ or 1931 xy with the Planckian locus.",
  'help.light-cie.what': "Shows whether a fixture sits on the Planckian locus (tungsten/daylight character) or has a green/magenta cast. Basis for matching fixtures from different makers before the camera white balance.",
  'help.light-cie.read': "Planckian locus with isotherms (CCT), lines Duv ±0.01/±0.02.\nAbove the locus (Duv > 0) = greenish, below (Duv < 0) = magenta.\nTrace per device (current or 20/60/300 readings), stored points, Δu′v′ to the chosen target (reference point, 3200/4300/5600/6500 K Planck, D65).\nGood: point on or very close to the locus, all fixtures close together.",
  'help.light-cie.try': "Hold the Opple first under a halogen/tungsten-style fixture, then into daylight.",
  'help.light-cie.check': "the point moves along the locus towards higher CCT (from the isotherms around 3000 K to those around 5000–6500 K).",
  'help.light-cie.pitfall': "Two lights with the same CCT can look different if their Duv differs; always check both.",
  'help.light-vector.one': "Colour deviation of the light from a target white as angle and distance (CIELUV).",
  'help.light-vector.what': "Matching light on set: shows in which direction (warmer, cooler, green, magenta) and how far a fixture is off target, and from 5 mired off suggests a CTO/CTB gel (Lee or Rosco).",
  'help.light-vector.read': "Centre = target white (3200/4300/5600/6500 K, D65 or reference point).\nAngle = hue h_uv, distance = saturation s_uv = 13·Δu′v′.\nDirection words warmer/cooler along the locus, green/magenta across it.\nMired to target and gel suggestion (not with target D65).\nGood: point in the centre; below 5 mired the app no longer suggests a gel.",
  'help.light-vector.try': "⚙ centre (target) \"5600 K Planck\", Opple under a 3200 K fixture.",
  'help.light-vector.check': "point towards \"warmer\", \"mired to target\" about −134 (10⁶/5600 − 10⁶/3200) with a CTB suggestion.",
  'help.light-vector.pitfall': "Gels correct only colour temperature in mired, not a gappy spectrum; an LED can measure \"right\" after gelling and still look wrong on camera.",
  'help.light-bands.one': "Calibrated counts of the Opple sensor's 6 or 8 colour filters, not spectral power.",
  'help.light-bands.what': "Rough look at spectral make-up: shows e.g. whether an LED lacks red or cyan. Complements CCT and Duv, which alone say nothing about gaps.",
  'help.light-bands.read': "One bar per filter channel, relative to the strongest channel; optionally as a ratio to the reference point (×1 = equal).\nGood: two lights with similar bar profiles behave more alike on camera.",
  'help.light-bands.try': "Measure tungsten, store it as a measuring point in the sidebar and mark it as reference (A), then measure a white LED.",
  'help.light-bands.check': "the bar profiles differ visibly; the reference profile is shown dashed alongside.",
  'help.light-bands.pitfall': "This is not a spectrum; 6–8 sample points cannot resolve narrow peaks or gaps.",
  'help.light-trend.one': "Lux, CCT and Duv over 30 s, 2 min, 10 min or 1 h, with mean and spread.",
  'help.light-trend.what': "Shows drift and fluctuation: fixtures warming up, changing daylight, dimmer effects. Helps decide when white balance needs redoing.",
  'help.light-trend.read': "Curves for lux, CCT, Duv (single or together); mean and σ per quantity, for lux also the coefficient of variation in %.\nGood: flat curves, small spread.",
  'help.light-trend.try': "Put the Opple in front of a freshly switched-on fixture for 2 minutes.",
  'help.light-trend.check': "warm-up drift in CCT or lux shows as a curve, then flattens.",
  'help.light-trend.pitfall': "Flicker is not measured here (Light Master 4/flicker untested); a calm curve does not mean flicker-free.",
  'help.light-map.one': "Capture points one after another into a grid: uniformity of brightness and colour.",
  'help.light-map.what': "Checks how evenly a surface is lit (green screen, stage, light box for white shading) and compares two lights with mired and green/magenta direction.",
  'help.light-map.read': "Grid of points as a map: illuminance in % of the brightest point, Δu′v′ to the mean (scale 0 … 0.01) or CCT to the mean (±500 K); header with uniformity min/max in % and max Δu′v′.\nGrid size, capture and comparison of two lights (mired, green/magenta with a Lee gel suggestion) in the sidebar → light meter.\nGood: uniformity near 100 %, small Δu′v′.",
  'help.light-map.try': "Sidebar → light meter → grid 3×3, capture the nine points on a wall one after another (blue frame = next point).",
  'help.light-map.check': "header \"9/9 points\" with uniformity and max Δu′v′.",
  'help.light-map.pitfall': "White shading needs a very even surface; Tektronix calls ±0.5 % typical and 1 % or more common – unevenness otherwise ends up as a \"shading error\" in the camera.",
  'help.light-spectrum.one': "For the Opple the filter channels over wavelength, for spectrometers the real spectrum.",
  'help.light-spectrum.what': "With a spectrometer (via ArgyllCMS) the spectral quality of a fixture can be judged, which decides skin rendering and camera matching; plus CRI/TLCI/TM-30 as ArgyllCMS computes them.",
  'help.light-spectrum.read': "Horizontal: wavelength 380–780 nm, vertical: relative value (peak = 100 %).\nGood: a continuous, even curve; deep dips indicate poor colour rendering.",
  'help.light-spectrum.try': "Sidebar → light meter → more meters → \"Open spectrum file …\" (Argyll .sp or CSV with wavelength, value).",
  'help.light-spectrum.check': "a curve appears over the wavelength axis, header with range and peak in nm.",
  'help.light-spectrum.pitfall': "With the Opple this is not a spectrum, only filter sample points; do not derive CRI/TLCI from it.",
  'help.light-swatch.one': "Shows the measured chromaticity of the light as a colour patch on screen.",
  'help.light-swatch.what': "Makes a reading tangible: crew and client see how warm, cool or greenish a light is, next to the Planckian point of the same CCT for comparison.",
  'help.light-swatch.read': "Patch \"measured (with Duv)\" in display colours (sRGB or P3, brightness normalised), next to it \"Planck, same CCT\" → the difference is the Duv part.\nHatching = outside the display gamut, the clipped colour is shown.\nGood: patch and Planckian reference look the same (Duv ≈ 0).",
  'help.light-swatch.try': "Measure a light with a visible green cast.",
  'help.light-swatch.check': "the patch looks greener than the Planckian reference next to it.",
  'help.light-swatch.pitfall': "The rendering depends on the display and its calibration; it illustrates, it does not measure.",
  'help.simulcast.one': "Heat map of how far the converted picture (e.g. SDR from HDR) differs from the real one, as ΔE ITP.",
  'help.simulcast.what': "In an HDR/SDR simulcast most viewers see the SDR conversion. The panel compares two stages of the source's chain – the HDR signal and the picture after the CST/LUT – both as display light, the SDR placed back with 100 % = 203 cd/m², and colours every area by ΔE ITP (ITU-R BT.2124). It shows where the conversion loses highlights, colour or shadow detail.",
  'help.simulcast.read': "Grey = below 1, not noticeable; blue → yellow → red up to the scale, white above.\nTop left: mean, 95th percentile and maximum, share above 1 and above the chosen limit.\nStages in ⚙: reference (real picture) and the compared one.\nGood: grey where the picture matters; colour only in highlights above SDR white.",
  'help.simulcast.try': "Test pattern \"PQ ramp with reference white 203\", in the sidebar under CST / LUT a CST to Rec.709 / BT.1886 with tone mapping \"Clip at the target peak\"; panel stages \"Signal\" and \"after CST\".",
  'help.simulcast.check': "the ramp stays grey up to about 203 cd/m² and turns coloured towards the right (clipped highlights); the bottom field at 203 cd/m² stays grey.",
  'help.simulcast.pitfall': "ΔE ITP assumes the most critical adaptation: values of 1–3 are rarely visible in a normal living room. Log stages are scene light and only give an order, not a visibility.",
  'help.encoder.one': "Programme against the return of a stream: delay, blocking, banding and A/V offset, live.",
  'help.encoder.what': "Small productions stream without a monitoring chain. Add the decoded stream (HLS, RTMP, SRT) as a source, show it in this panel and pick the programme (what goes into the encoder) in ⚙. The panel compares both continuously and shows what the encoder and the stream path add.",
  'help.encoder.read': "Delay: how far the return lags behind, with how sure the match is (moving content needed).\nBlocking B/A: differences across the 8-pixel block boundaries against those inside the blocks; 1 = no block structure. Programme → return.\nBanding: index after CAMBI (simplified); higher = more steps in flat gradients.\nA/V: offset of each source from flash and beep, and the difference the stream adds (BT.1359-1).\nGood: return close to the programme in every row.",
  'help.encoder.try': "Two sources: the test pattern \"A/V sync\" with the generator beep as programme, the same signal pushed through ffmpeg (or an RTSP test stream) as return. Panel source = return, ⚙ programme = the test pattern.",
  'help.encoder.check': "a delay appears once the picture moves; the A/V line shows both offsets and their difference.",
  'help.encoder.pitfall': "Blocking only measures at the native analysis width (bridge width \"native\"); a scaled analysis picture smears the 8-pixel grid.",
  'help.lens.one': "White shading and centre colour of the lens on a flat white field, stored per lens and zoom and compared after a lens change.",
  'help.lens.what': "Every lens shades differently (fall-off to the edges, green/magenta top and bottom, a colour of its own), and it changes with the zoom. Cameras keep the corrections in lens files; this panel measures the picture: saw and parabola per channel, the centre colour as R/G and B/G, stored as a fingerprint. After a lens change it shows what differs from the stored fingerprint and which control to turn.",
  'help.lens.read': "Map: brightness of each area against the centre (blue darker, orange brighter, ±10 %).\nTable: saw H/V and parabola H/V per channel in % of the centre, rest = what the four terms do not explain.\nΔ rows: live minus stored, in percentage points; the largest one is named.\nGood: Δ near 0, rest small.",
  'help.lens.try': "Camera on an evenly lit white card or diffuser (fill the frame, slightly defocused), enter lens and zoom in ⚙, \"Store fingerprint\". Zoom in, store a second one, then zoom back.",
  'help.lens.check': "back at the first zoom the panel picks that fingerprint and the Δ rows are near 0.",
  'help.lens.pitfall': "Uneven light looks like lens shading – the field has to be even to a fraction of a percent (Tektronix: ±0.5 % typical with a diffuser).",
  'help.shguide.one': "Guided shading sequence with live measurement: black, black balance, flare, grey scale, white, knee, matrix – plus the camera data of the Touch Shading target.",
  'help.shguide.what': "For whoever shades without a mentor: each step says what to put in front of the lens, measures the measuring frame and names the control to turn and in which direction.",
  'help.shguide.read': "Y′ and R′−G′ / B′−G′ in the measuring frame; knee: peak and clipped share of the whole picture; flare: ΔY′ and chroma shift between black with iris closed and open.",
  'help.shguide.try': "\"Black\" test pattern, step 1, then \"Grey 50 %\" for step 4.",
  'help.shguide.check': "With \"Black\" step 2 reads ✓ (R′−G′ and B′−G′ +0.0 %); with \"Grey 50 %\" step 4 reads Y′ about 50 % and ✓.",
  'help.shguide.pitfall': "The flare step needs a really black object; a dark grey shows as flare.",
  'help.sdi.one': "What the SDI signal says about itself: ST 352 payload ID, HDR metadata, timecode, captions and audio packets from a DeckLink input.",
  'help.sdi.what': "SDI carries ancillary packets beside the picture. The ST 352 payload ID names format, rate, sampling, bit depth, colorimetry and transfer (SDR, HLG, PQ); ST 2108-1 carries mastering display and MaxCLL; ST 12-2 carries LTC/VITC timecode. The panel decodes them and warns when the signal is flagged differently from what the scopes read.",
  'help.sdi.read': "Top: ST 352 bytes and their meaning. Yellow line: the flag disagrees with the transfer or matrix of the source – ⚙ offers the switch.\nBelow: HDR metadata, timecode, AFD, presence of CEA-708/608 and ST 299 audio groups, then every packet type with line, DID/SDID, count and data in hex.",
  'help.sdi.try': "Add a DeckLink input (Sources → DeckLink…) with an SDI signal and open this panel.",
  'help.sdi.check': "the ST 352 line shows the format the source outputs (for example 1080p50, 4:2:2, 10 bit) and no yellow line once transfer and matrix agree.",
  'help.sdi.pitfall': "Converters and recorders often rewrite or drop ST 352 – a missing or wrong flag says more about the chain than about the camera. Not yet tested with a card (#116).",
  // --- end scope texts ---
} satisfies Messages;
